using System;
using System.Threading.Tasks;

public enum CircuitState { Closed, Open, HalfOpen }

public class MiniCircuitBreaker
{
    public CircuitState State { get; private set; } = CircuitState.Closed;
    private int _consecutiveFailures = 0;
    private readonly int _failureThreshold = 3;

    public async Task<string> ExecuteAsync(Func<Task<string>> action, Func<string> fallback)
    {
        if (State == CircuitState.Open)
        {
            Console.WriteLine("[CIRCUIT OPEN] Fast-fail! Menolak panggilan jaringan, langsung fallback.");
            return fallback();
        }

        try
        {
            var res = await action();
            _consecutiveFailures = 0;
            return res;
        }
        catch
        {
            _consecutiveFailures++;
            Console.WriteLine($"[FAILURE] Gagal ke-{_consecutiveFailures}/{_failureThreshold}");

            if (_consecutiveFailures >= _failureThreshold)
            {
                State = CircuitState.Open;
                Console.WriteLine("[CIRCUIT BREAKER TRIPPED] Ambang batas terlampaui! State sekarang OPEN.");
            }

            return fallback();
        }
    }
}

public class Program
{
    public static async Task Main()
    {
        var breaker = new MiniCircuitBreaker();
        Func<Task<string>> brokenService = () => throw new Exception("503 Service Unavailable");
        Func<string> fallback = () => "Default Cached Response (Degraded)";

        Console.WriteLine("--- Menjalankan 5 Panggilan Berturut-turut ---");
        for (int i = 1; i <= 5; i++)
        {
            Console.WriteLine($"\nPanggilan ke-{i}:");
            var result = await breaker.ExecuteAsync(brokenService, fallback);
            Console.WriteLine($"Hasil: {result} | Status Breaker: {breaker.State}");
        }
    }
}

